attributes:
@click.option(
    "--posts",
    default=100,
    help="Number of posts to create in each topic (default: 100).",
)

@click.option(
    "--initdb",
    "-i",
    is_flag=True,
    help="Initializes the database before populating it.",
)

@click.option(
    "--host",
    "-h",
    default=None,
    help="The interface to bind FlaskBB to. Defaults to '127.0.0.1'.",
)

@click.option(
    "--worker-class",
    "-k",
    default=None,
    help="The type of worker to use. Defaults to 'sync'.",
)

@click.option(
    "--plugin",
    "-p",
    type=click.STRING,
    help="Updates the language of the given plugin.",
)

@click.option(
    "--plugin",
    "-p",
    type=click.STRING,
    help="Compiles the translations for a given plugin.",
)

@click.option(
    "--group",
    "-g",
    help="The group of the user.",
    type=click.Choice(["admin", "super_mod", "mod", "member"]),
)

@click.option(
    "--group",
    "-g",
    help="The group of the user.",
    type=click.Choice(["admin", "super_mod", "mod", "member"]),
)

@allows.requires(
        CanPostReply,
        on_fail=FlashAndRedirect(
            message=_("You are not allowed to post a reply to this topic."),
            level="warning",
            endpoint=lambda *a, **k: url_for(
                "forum.view_topic",
                topic_id=k["topic_id"],
            ),
        ),
    )
